using Microsoft.EntityFrameworkCore;
using Osynix.Ats.Data;
using Osynix.Ats.Domain;
namespace Osynix.Ats.Services;
public record EmployerSubmittedProfile(EmployerProfileSubmission Submission,string Candidate,string Position,string Reference,string Recruiter);
public class EmployerSubmissionService(Access access,EmployerService employer,IDbContextFactory<AtsDbContext> factory,RecruitmentUpdates updates){
 public static readonly string[] Decisions=["Shortlisted","Changes Requested","Interview Requested","Rejected"];
 public async Task Submit(IEnumerable<Guid> assessmentIds){var active=await access.Context();if(active?.Membership is null)throw new UnauthorizedAccessException("Switch To Your Employer Workspace To Submit Profiles.");var uid=await access.UserId();var ids=assessmentIds.Distinct().ToList();if(ids.Count is <1 or >50)throw new InvalidOperationException("Select 1–50 Saved Profiles.");foreach(var id in ids)await access.RequireApplication(id);await using var db=await factory.CreateDbContextAsync();await using var tx=await db.Database.BeginTransactionAsync();if(!await db.WorkspaceMemberships.AnyAsync(m=>m.Id==active.Membership.Id&&m.UserId==uid&&m.WorkspaceId==active.Id&&m.Status=="Active"))throw new UnauthorizedAccessException("Your Team Membership Is No Longer Active.");var rows=await db.Assessments.Where(a=>ids.Contains(a.Id)&&a.State=="Saved").ToListAsync();if(rows.Count!=ids.Count||rows.Any(a=>a.Stage=="Hired"))throw new InvalidOperationException("Choose Saved Profiles That Have Not Been Hired.");foreach(var a in rows){var position=await db.Positions.SingleAsync(p=>p.Id==a.PositionId);if(position.Status is not("Active" or "On Hold"))throw new InvalidOperationException("Submit Profiles Only For Open Employer Positions.");if(position.WorkspaceId!=active.Id)throw new UnauthorizedAccessException();var submission=await db.EmployerProfileSubmissions.SingleOrDefaultAsync(s=>s.WorkspaceId==active.Id&&s.AssessmentId==a.Id);if(submission is null){submission=new(){WorkspaceId=active.Id!.Value,AssessmentId=a.Id};db.EmployerProfileSubmissions.Add(submission);}submission.SubmittedBy=uid;submission.SubmittedUtc=DateTime.UtcNow;submission.AssessmentVersion=a.VersionNumber;submission.Status="Awaiting Employer Review";submission.Remarks="";submission.FeedbackUtc=null;if(!await db.AssessmentVersions.AnyAsync(v=>v.AssessmentId==a.Id&&v.Number==a.VersionNumber))db.AssessmentVersions.Add(DatabaseInitializer.VersionOf(a));a.Stage="Awaiting Employer Review";AtsService.Audit(db,uid,"Profile submitted to Employer",submission.Id.ToString(),position.Reference,a.CandidateId,a.Id);}await db.SaveChangesAsync();await tx.CommitAsync();updates.Publish();}
 public async Task<List<EmployerSubmittedProfile>> Inbox(){var overview=await employer.Overview();var positionIds=(await new AtsService(factory,access).Positions()).Select(p=>p.Id).ToList();await using var db=await factory.CreateDbContextAsync();return await (from s in db.EmployerProfileSubmissions.AsNoTracking() join a in db.Assessments on s.AssessmentId equals a.Id join p in db.Positions on a.PositionId equals p.Id join u in db.Users on s.SubmittedBy equals u.Id where s.WorkspaceId==overview.Workspace.Id&&positionIds.Contains(p.Id) orderby s.SubmittedUtc descending select new EmployerSubmittedProfile(s,a.CandidateName,p.Title,p.Reference,u.FullName.Length>0?u.FullName:u.UserName!)).ToListAsync();}
 public async Task<List<EmployerProfileSubmission>> Feedback(){var allowed=await new AtsService(factory,access).Assessments();var ids=allowed.Select(a=>a.Id).ToList();await using var db=await factory.CreateDbContextAsync();return await db.EmployerProfileSubmissions.AsNoTracking().Where(s=>ids.Contains(s.AssessmentId)).ToListAsync();}
 public async Task Decide(Guid id,Guid revision,string decision,string remarks){var overview=await employer.Overview();if(!Decisions.Contains(decision)||remarks.Length>5000)throw new InvalidOperationException("Choose A Valid Employer Decision And Remarks Up To 5,000 Characters.");await using var db=await factory.CreateDbContextAsync();var s=await db.EmployerProfileSubmissions.SingleOrDefaultAsync(s=>s.Id==id&&s.WorkspaceId==overview.Workspace.Id)??throw new UnauthorizedAccessException();await access.RequireApplication(s.AssessmentId);if(s.Revision!=revision)throw new InvalidOperationException("This Submission Changed. Reload Before Reviewing.");s.Status=decision;s.Remarks=remarks.Trim();s.FeedbackUtc=DateTime.UtcNow;var a=await db.Assessments.SingleAsync(a=>a.Id==s.AssessmentId);if(a.Stage=="Awaiting Employer Review")a.Stage=decision switch{"Shortlisted"=>"Shortlisted","Rejected"=>"Rejected",_=>"HR Screening"};AtsService.Audit(db,overview.Workspace.OwnerId,"Employer profile feedback",s.Id.ToString(),decision,a.CandidateId,a.Id);await db.SaveChangesAsync();updates.Publish();}
}
